import "@xpyjs/gantt-core/style.css";

const ganttContainer = document.getElementById("gantt-container");
if (!ganttContainer) {
  throw new Error("Gantt container not found");
}

const gantt = new XGantt(ganttContainer, {
  width: 800,
  height: 400,
  border: {
    show: true
  },
  data: [
    {
      id: "1",
      name: "项目规划",
      startTime: "2025-01-01",
      endTime: "2025-01-15",
      progress: 80,
      children: [
        {
          id: "1-1",
          name: "需求分析",
          startTime: "2025-01-01",
          endTime: "2025-01-05",
          progress: 100
        },
        {
          id: "1-2",
          name: "技术选型",
          startTime: "2025-01-06",
          endTime: "2025-01-15",
          progress: 90
        }
      ]
    },
    {
      id: "2",
      name: "开发阶段",
      startTime: "2025-01-16",
      endTime: "2025-01-28",
      progress: 60,
      children: [
        {
          id: "2-1",
          name: "前端开发",
          startTime: "2025-01-16",
          endTime: "2025-01-28",
          progress: 80
        },
        {
          id: "2-2",
          name: "后端开发",
          startTime: "2025-01-16",
          endTime: "2025-01-28",
          progress: 70
        }
      ]
    },
    {
      id: "3",
      name: "测试阶段",
      startTime: "2025-01-28",
      endTime: "2025-02-05",
      progress: 50
    }
  ],
  table: {
    columns: [
      {
        field: "name",
        label: "任务名称",
        width: 150,
        align: "left",
        merge: (value, data, colIndex, level) => {
          if (level === 1) {
            return { col: 3, row: 1 };
          }
        }
      },
      {
        field: "startTime",
        label: "开始时间",
        width: 150,
        merge: (value, data, colIndex, level) => {
          if (data.name === "前端开发") {
            return { col: 1, row: 2 };
          }
        }
      },
      {
        field: "endTime",
        label: "结束时间",
        width: 150,
        merge: (value, data, colIndex, level) => {
          if (data.name === "前端开发") {
            return { col: 1, row: 2 };
          }
        }
      }
    ]
  }
});
